-- Roktolagbe: seed data
--
-- GENERATED FILE. Do not edit by hand.
-- Regenerate with:  node scripts/build-setup-sql.mjs
--
-- Run this after setup.sql. Safe to run more than once.
-- 
-- Geography is derived from OpenStreetMap and is licensed ODbL.
-- See supabase/seed/README.md.

begin;

-- ==========================================================================
-- 001_districts.sql
-- ==========================================================================

-- Seed: all 64 districts of Bangladesh
--
-- GENERATED FILE. Do not edit by hand.
-- Regenerate with:  node scripts/build-geo-seed.mjs
--
-- Source: ifahimreza/bangladesh-geojson, ODbL, derived from OpenStreetMap.
-- ODbL is share-alike: this derived data carries the same licence.
-- Corrections are welcome and are a one line pull request.

on conflict (id) do update set
  name_en     = excluded.name_en,
  name_bn     = excluded.name_bn,
  division_en = excluded.division_en,
  division_bn = excluded.division_bn,
  lat         = excluded.lat,
  lng         = excluded.lng;

-- ==========================================================================
-- 002_upazilas.sql
-- ==========================================================================

-- Seed: all 494 upazilas of Bangladesh
--
-- GENERATED FILE. Do not edit by hand.
-- Regenerate with:  node scripts/build-geo-seed.mjs
--
-- Source: ifahimreza/bangladesh-geojson, ODbL, derived from OpenStreetMap.
-- ODbL is share-alike: this derived data carries the same licence.
-- Corrections are welcome and are a one line pull request.
--
-- 25 upazila(s) have no usable boundary polygon and are seeded with a
-- NULL centroid. The app falls back to the district centroid for those.

on conflict (id) do update set
  district_id = excluded.district_id,
  name_en     = excluded.name_en,
  name_bn     = excluded.name_bn,
  lat         = excluded.lat,
  lng         = excluded.lng;

-- ==========================================================================
-- 003_hospitals.sql
-- ==========================================================================

-- Seed: starter hospital list
--
-- GENERATED FILE. Regenerate with:  node scripts/build-hospital-seed.mjs
--
-- Names are curated by hand. Positions come from Nominatim (OpenStreetMap,
-- ODbL) and every one was checked to be within 60km of its district centre.
-- 42 hospital(s) could not be placed and have a NULL position; they still
-- appear in the dropdown, and an admin can set the pin from master data.
--
-- This is a starting point, not a register. Add your own with plain INSERTs or
-- through the admin panel.

on conflict do nothing;

